// Regenerates base44/shared/prompts.ts from P4's engine/prompts/*.md and *.schema.json (verbatim).
// Run from anywhere: node /abs/path/to/app/scripts/gen-prompts.mjs
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const app = fileURLToPath(new URL("..", import.meta.url));
const engine = fileURLToPath(new URL("../../../engine/prompts/", import.meta.url));
const read = (f) => readFileSync(engine + f, "utf8");

const out = `// GENERATED by scripts/gen-prompts.mjs: verbatim copies of engine/prompts/* (owner: P4).
// Do not edit here. Change the engine/ files, then rerun the script.
export const DETECT_PROMPT = ${JSON.stringify(read("detect.md"))};

export const DETECT_SCHEMA = ${JSON.stringify(JSON.parse(read("detect.schema.json")), null, 2)};

export const REWRITE_PROMPT = ${JSON.stringify(read("rewrite.md"))};

export const REWRITE_SCHEMA = ${JSON.stringify(JSON.parse(read("rewrite.schema.json")), null, 2)};

export const ABSOLUTES_PROMPT = ${JSON.stringify(read("absolutes.md"))};

export const CONTRADICT_PROMPT = ${JSON.stringify(read("contradict.md"))};
`;
writeFileSync(app + "base44/shared/prompts.ts", out);

// verbatim check: every prompt round-trips byte for byte
const back = readFileSync(app + "base44/shared/prompts.ts", "utf8");
for (const [name, file] of [
  ["DETECT_PROMPT", "detect.md"],
  ["REWRITE_PROMPT", "rewrite.md"],
  ["ABSOLUTES_PROMPT", "absolutes.md"],
  ["CONTRADICT_PROMPT", "contradict.md"],
]) {
  const m = back.match(new RegExp(`export const ${name} = (".*?");\\n`, "s"));
  if (JSON.parse(m[1]) !== read(file)) throw new Error(`${name} is not verbatim`);
}
console.log("prompts.ts regenerated, prompts verbatim");
